# AppendConstrainedStep, and only treat EndsWithRightDelimiter as the closing
# event. Maintain a bounded checkpoint only for local recovery around a span,
# but otherwise keep decoding forward-moving rather than rollback-driven.
# Prefer continuing after an early scratch span and only stop after a later
# closed span when the derivation appears final-ready.
# CSD_RATIONALE_END
phase = "reasoning"
in_span = False
closed_spans = 0
final_ready = False
checkpoint = []
have_checkpoint = False

# invariant helpers.lm == lm
